test('creates a transaction with a toggled sign in mobile transaction entry', async ({
  page,
}) => {
  await page.setViewportSize({ width: 350, height: 600 });
  await page.goto('/');

  await page.getByText('Accounts', { exact: true }).click();
  await page.getByText('Bank of America').first().click();

  await page.getByRole('button', { name: /add transaction/i }).click();

  const amountField = page.getByLabel('Amount');
  await amountField.fill('12.34');

  await page.getByText('±').click();
  await expect(amountField).toHaveValue('-12.34');

  await page.getByPlaceholder('Payee').fill('Test Payee');
  await page.getByPlaceholder('Category').fill('Food');
  await page.getByPlaceholder('Notes').fill('Created by Playwright');

  await page.getByRole('button', { name: /add|save|done/i }).click();

  await expect(page.getByText('Test Payee')).toBeVisible();
});

