import { test, expect } from './fixtures';

test('updates the three select settings on the settings page', async ({ page }) => {
  await page.goto('/settings');

  const selects = page.getByRole('combobox');
  await expect(selects).toHaveCount(3);

  for (let i = 0; i < 3; i++) {
    const select = selects.nth(i);
    await expect(select).toBeVisible();

    const initialValue = await select.inputValue();
    const optionsCount = await select.locator('option').count();
    expect(optionsCount).toBeGreaterThan(1);

    const targetIndex = (await select.evaluate(el => el.selectedIndex)) === 0 ? 1 : 0;
    await select.selectOption({ index: targetIndex });

    await expect(select).not.toHaveValue(initialValue);
  }
});

